algorithms.Bubble Sort:
mt19937 random(42);
for (int size=0;size<40;++size) {
    vector<int> a(size);
    for (int& value:a) value=static_cast<int>(random()%100);
    auto expected=a; sort(expected.begin(),expected.end());
    bubbleSort(a); check(a==expected);
}
vector<int> descending{5,4,3,2,1}, equal{7,7,7};
bubbleSort(descending); check(descending==vector<int>({1,2,3,4,5}));
bubbleSort(equal); check(equal==vector<int>({7,7,7}));
vector<int> negative{-4,0,-9,3,-4}; bubbleSort(negative); check(negative==vector<int>({-9,-4,-4,0,3}));

